EQ_P1 = {
    "fft_fastconv": ["`fcnt == N - 2` instead of `N - 1` as the last feed clock (the block is fed one word short): the FFT pipelines take their data every clock whatever in_valid says (in_valid and in_sof only mark the start of the frame), and the ring read address keeps following fcnt, so the last word reaches the transform in the clock in which it would have been presented; only the valid flag of that clock differs, and nothing uses it",
                     "`wr_ptr <= 0` instead of `LOGN'(L - 1)` at the end of the clear: the ring is cleared everywhere, so starting the first block at position 0 (and feeding it from position B) presents the same L - 1 zeros followed by the same B samples, only rotated in memory; every later block starts at the pointer the same way",
                     "`hmem[qcnt]` instead of `hmem[qpos]` (qpos = 0 at the first word of a frame): qcnt wraps to 0 after N words, so for the whole frames the forward FFT delivers it equals qpos",
                     "the same-clock priority of a write-1-to-clear of SAT against the datapath's SAT pulse (`!sat_pulse` in the clear): a clear that loses to a pulse in the same clock cannot be arranged by a bench that sees only whole-clock behaviour; it is stated in the contract and covered by formal/jobs.yaml"],
    "fft_mdc2": ["`pos = cnt` instead of `ev_sof ? 0 : cnt`: the counter wraps at N/2 and holds between frames, so for the contiguous frames the sub-pipelines deliver it equals the restarted counter",
                 "`vv` fed from the odd pipeline's valid instead of the even one's: the two pipelines run in lockstep, their controls are identical"],
    "fft_bfp": ["`wpos = wcnt` instead of `in_sof ? 0 : wcnt` in fft_bfp_out: the write counter wraps at N, so for the contiguous frames of exactly N words that both cores deliver it equals the restarted counter (the OR accumulator does restart at in_sof: mutant acc_not_restarted)",
                "`bl = i + 1` guarded by `i < WC - 1`: bit WC - 1 of the OR is the sign of the XORed magnitude, always 0, so the guard never changes the result"],
}
